// Üretilen dosya: tool/ozgun/uret.py. Matematik · Polinomlar ve çarpanlara ayırma (kolay).
const ozMathematics8Kolay = <(String, String, List<String>, String)>[
  ('P(x) = √2·x³ − πx + 1 ifadesi için aşağıdakilerden hangisi doğrudur?', 'Gerçek katsayılı bir polinomdur', ['Katsayıları irrasyonel olduğu için polinom değildir', 'Yalnız π\'li terim atılırsa polinom olur', 'Rasyonel katsayılı bir polinomdur'], 'Polinom olmak için değişkenin üsleri doğal sayı olmalıdır; katsayıların irrasyonel olması engel değildir. √2 ve π gerçek sayı olduğundan ifade gerçek katsayılı bir polinomdur.'),
  ('Bir ifadenin x değişkenine göre polinom sayılabilmesi için her terimdeki x üssünün ait olması gereken küme hangisidir?', 'Doğal sayılar', ['Tam sayılar', 'Rasyonel sayılar', 'Pozitif gerçek sayılar'], 'Polinomun her teriminde değişkenin üssü 0, 1, 2, … gibi bir doğal sayıdır. Negatif ya da kesirli üs (x⁻¹, √x gibi) ifadeyi polinom olmaktan çıkarır.'),
  ('x³ + 2x²y − 5y³ polinomunda olduğu gibi bütün terimlerinin derecesi aynı olan polinomlara ne ad verilir?', 'Homojen polinom', ['Monik polinom', 'Sabit polinom', 'İndirgenemez polinom'], 'Her teriminin toplam derecesi eşit olan polinomlara homojen polinom denir. Örnekteki üç terimin her biri üçüncü derecedendir.'),
  ('x³ − 4x + 7 gibi en yüksek dereceli teriminin katsayısı 1 olan polinomlara ne ad verilir?', 'Monik polinom', ['Homojen polinom', 'Simetrik polinom', 'Özdeş polinom'], 'Baş katsayısı 1 olan polinomlara monik (birincil) polinom denir. Rasyonel kök teoreminde bu polinomların rasyonel kökleri tam sayı olmak zorundadır.'),
  ('P(x) = (m − 3)x³ + (m + 1)x² − 4 polinomu ikinci dereceden olduğuna göre baş katsayısı kaçtır?', '4', ['3', '1', '−4'], 'İkinci dereceden olması için x³\'ün katsayısı sıfır olmalı: m = 3. Bu durumda x²\'nin katsayısı m + 1 = 4 olur ve baş katsayıdır.'),
  ('P(x) = (a + 2)x² + (b − 1)x + c − 5 ifadesi sıfır polinomu olduğuna göre a + b + c toplamı kaçtır?', '4', ['2', '6', '−4'], 'Sıfır polinomunda tüm katsayılar sıfırdır: a = −2, b = 1, c = 5. Toplam −2 + 1 + 5 = 4 bulunur.'),
  ('P(x) = (k − 1)x² + (n + 2)x + 7 bir sabit polinom olduğuna göre P(2026) değeri kaçtır?', '7', ['0', '2026', '2033'], 'Sabit polinomda x\'li terimlerin katsayıları sıfırdır; geriye P(x) = 7 kalır. Bu yüzden x\'e hangi değer verilirse verilsin sonuç 7\'dir.'),
  ('P(x) = 5 sabit polinomunun derecesi kaçtır?', '0', ['1', '5', 'Tanımsızdır'], 'Sıfırdan farklı bir sabit polinom 5 = 5·x⁰ biçiminde yazılır; derecesi 0\'dır. Derecesi tanımsız olan yalnız sıfır polinomudur.'),
  ('Her x için (2x − 1)(x + a) = 2x² + 5x − 3 özdeşliği sağlandığına göre a kaçtır?', '3', ['2', '−3', '5/2'], 'Sol taraf açılınca 2x² + (2a − 1)x − a olur. Katsayılar eşitlenirse 2a − 1 = 5 ve −a = −3; ikisinden de a = 3 çıkar.'),
  ('(x + 2)⁵ ifadesi açılıp benzer terimler toplandığında kaç terimli bir polinom elde edilir?', '6', ['5', '10', '32'], 'n. kuvvetten bir iki terimli açıldığında x\'in üsleri n, n − 1, …, 0 olur; toplam n + 1 terim çıkar. Burada 5 + 1 = 6 terim vardır.'),
  ('P(x) = x⁴ − 3x² + x polinomunda x³\'lü terimin katsayısı ile x\'li terimin katsayısının toplamı kaçtır?', '1', ['0', '−2', '4'], 'Yazılmayan x³ teriminin katsayısı 0\'dır; x\'in katsayısı 1\'dir. Toplam 0 + 1 = 1 olur.'),
  ('P(x) = 2x + 3 olmak üzere P(P(x)) polinomu aşağıdakilerden hangisidir?', '4x + 9', ['4x + 6', '2x + 6', '4x² + 9'], 'P(P(x)) = 2(2x + 3) + 3 = 4x + 6 + 3 = 4x + 9 bulunur.'),
  ('Birinci dereceden bir P(x) polinomu için P(1) = 5 ve P(3) = 11\'dir. P(x) polinomunun sabit terimi kaçtır?', '2', ['3', '5', '−1'], 'P(x) = ax + b alınırsa a + b = 5 ve 3a + b = 11; çıkarınca a = 3, b = 2 olur. Sabit terim 2\'dir.'),
  ('P(x, y) = 3x²y − xy² + 7 polinomunun x = 1 ve y = −2 için aldığı değer kaçtır?', '−3', ['3', '−11', '1'], '3·1·(−2) − 1·4 + 7 = −6 − 4 + 7 = −3 bulunur.'),
  ('Bir polinom x³ − 2 polinomuna bölündüğünde elde edilebilecek kalanın derecesi en çok kaçtır?', '2', ['3', '1', '0'], 'Kalanın derecesi bölenin derecesinden küçük olmak zorundadır. Bölen üçüncü dereceden olduğundan kalan en çok ikinci dereceden olabilir.'),
  ('Bir polinom bölmesinde bölen ikinci, bölüm dördüncü dereceden ise bölünen polinomun derecesi kaçtır?', '6', ['8', '4', '2'], 'Bölünen = bölen·bölüm + kalan ve kalanın derecesi bölenden küçüktür. Bu yüzden bölünenin derecesi 2 + 4 = 6\'dır.'),
  ('x − 2\'ye bölündüğünde 5 kalanını veren bir P(x) için x²·P(x) + 1 ifadesi aynı iki terimliye bölünürse geriye hangi sayı kalır?', '21', ['6', '11', '26'], 'Kalan teoremine göre aranan değer x = 2 için hesaplanır: 2²·P(2) + 1 = 4·5 + 1 = 21.'),
  ('Dördüncü dereceden x⁴ − 1 iki terimlisini birinci dereceden x − 1 çarpanına ayırınca diğer çarpan ne olur?', 'x³ + x² + x + 1', ['x³ − x² + x − 1', 'x³ + 1', 'x³ + x² + x'], 'x⁴ − 1 = (x − 1)(x³ + x² + x + 1) eşitliği çarpım açılarak doğrulanabilir; bölme kalansızdır.'),
  ('2x⁴ − 3x² + 5 polinomunu Horner tablosuyla bölmek için üst satıra yazılması gereken katsayı dizisi hangisidir?', '2, 0, −3, 0, 5', ['2, −3, 5', '2, −3, 0, 5', '2, 0, −3, 5'], 'Horner tablosunda eksik dereceli terimlerin katsayısı 0 olarak yazılmalıdır; x³ ve x terimleri olmadığından onların yerine 0 konur.'),
  ('Horner yöntemiyle bir polinom x + 3 ikiterimlisine bölünürken tablonun sol köşesine yazılan çarpan hangisidir?', '−3', ['3', '1/3', '−1/3'], 'Horner tablosunda bölenin kökü kullanılır. x + 3 = 0 eşitliğinden x = −3 olduğundan çarpan −3\'tür.'),
  ('P(x) = (x − 2)³(x + 1)²(x − 5) polinomunun birbirinden farklı köklerinin sayısı ve katlılıklarıyla birlikte sayılan köklerinin sayısı sırasıyla hangisidir?', '3 ve 6', ['3 ve 3', '6 ve 6', '3 ve 5'], 'Farklı kökler 2, −1 ve 5\'tir. Katlılıklar 3, 2 ve 1 olduğundan toplam 6 kök vardır; bu sayı polinomun derecesine eşittir.'),
  ('2x³ − 5x² + 4x + 7 polinomunun köklerinin çarpımı kaçtır?', '−7/2', ['7/2', '5/2', '−7'], 'ax³ + bx² + cx + d polinomunda kökler çarpımı −d/a\'dır. Burada −7/2 bulunur.'),
  ('x³ + 2x² − 5x + 1 polinomunun kökleri x₁, x₂, x₃ ise x₁x₂ + x₁x₃ + x₂x₃ toplamı kaçtır?', '−5', ['5', '−2', '1'], 'Üçüncü dereceden polinomda ikişerli çarpımların toplamı c/a\'ya eşittir: −5/1 = −5.'),
  ('Gerçek katsayılı bir polinomun bir kökü 1 − 2i karmaşık sayısıdır. Hangi sayının da kök olduğu kesindir?', '1 + 2i', ['−1 − 2i', '−1 + 2i', '2 − i'], 'Gerçek katsayılı polinomlarda gerçek olmayan kökler karmaşık eşlenikleriyle birlikte bulunur; 1 − 2i\'nin eşleniği 1 + 2i\'dir.'),
  ('P(x) polinomunun köklerinden biri 3\'tür. Buna göre P(x − 2) polinomunun kesin olarak bilinen bir kökü hangisidir?', '5', ['1', '3', '−1'], 'P(x − 2) = 0 olması için x − 2 = 3 olmalıdır; buradan x = 5 bulunur.'),
  ('6a²b − 9ab² ifadesi ortak çarpan parantezine alındığında hangi biçime gelir?', '3ab(2a − 3b)', ['3a(2ab − 3b²)', 'ab(6a − 9b)', '3ab(2a − 9b)'], 'Katsayıların EBOB\'u 3, iki terimde de bulunan değişkenler a ve b\'dir. Ortak çarpan 3ab dışarı alınınca içeride 2a − 3b kalır; yalnız bu biçim tam olarak ortak çarpan almıştır.'),
  ('−3x² + 12x ifadesi baş katsayısı negatif bir ortak çarpan parantezine alınırsa hangi biçim elde edilir?', '−3x(x − 4)', ['−3x(x + 4)', '3x(x − 4)', '−3(x² + 4x)'], 'Her iki terim −3x\'e bölünür: −3x² ÷ (−3x) = x, 12x ÷ (−3x) = −4. Sonuç −3x(x − 4)\'tür.'),
  ('2x³ − 8x ifadesi tamamen çarpanlarına ayrıldığında hangisi bulunur?', '2x(x − 2)(x + 2)', ['2x(x − 4)(x + 4)', '2(x − 2)(x + 2)', 'x(2x − 4)(2x + 4)'], 'Önce ortak çarpan 2x alınır: 2x(x² − 4). Ardından x² − 4 iki kare farkı olarak (x − 2)(x + 2) biçiminde ayrılır.'),
  ('xy + 3x − 2y − 6 dört terimlisi ikişerli gruplanırsa hangi çarpım elde edilir?', '(x − 2)(y + 3)', ['(x + 2)(y − 3)', '(x − 3)(y + 2)', '(x − 2)(y − 3) + 12'], 'İlk iki terimden x, son ikisinden −2 alınır: x(y + 3) − 2(y + 3) = (x − 2)(y + 3).'),
  ('x² − y² = 24 ve x + y = 6 olduğuna göre x − y farkı kaçtır?', '4', ['3', '18', '12'], 'x² − y² = (x − y)(x + y) olduğundan 24 = (x − y)·6 ve x − y = 4 bulunur.'),
  ('1001·999 çarpımı iki kare farkı özdeşliği yardımıyla hesaplanırsa sonuç kaçtır?', '999 999', ['1 000 001', '999 001', '998 999'], '1001·999 = (1000 + 1)(1000 − 1) = 1000² − 1 = 999 999 bulunur.'),
  ('Kesirli sabit içeren x² − 1/9 ifadesi hangi iki çarpana ayrılır?', '(x − 1/3)(x + 1/3)', ['(x − 1/9)(x + 1/9)', '(x − 1/3)²', '(x − 3)(x + 3)/9'], '1/9 = (1/3)² olduğundan ifade x² − (1/3)² biçiminde bir iki kare farkıdır ve (x − 1/3)(x + 1/3) olarak yazılır.'),
  ('a(b − c) − b(b − c) ifadesinin çarpanlara ayrılmış hâli hangisidir?', '(b − c)(a − b)', ['(b − c)(a + b)', '(a − c)(a − b)', '(b − c)²(a − b)'], 'İki terimde ortak olan b − c parantezi dışarı alınınca içeride a − b kalır.'),
  ('Kenarı 13 cm olan kare biçimli bir kartonun köşesinden kenarı 7 cm olan bir kare kesiliyor. Kalan alanı tek bir çarpımla hesaplayan öğrenci hangi sonucu bulur?', '120 cm²', ['36 cm²', '100 cm²', '140 cm²'], 'Kalan alan 13² − 7² = (13 − 7)(13 + 7) = 6·20 = 120 cm²\'dir. İki kare farkı, alanların farkını tek bir çarpıma dönüştürür.'),
  ('(2x − 3y)² ifadesi açıldığında ortadaki terim hangisidir?', '−12xy', ['−6xy', '12xy', '−12x²y²'], '(a − b)² = a² − 2ab + b² özdeşliğinde ortadaki terim −2ab\'dir: −2·(2x)·(3y) = −12xy.'),
  ('x² + kx + 49 üç terimlisinin bir tam kare olması için k\'nin alabileceği pozitif değer kaçtır?', '14', ['7', '49', '98'], 'x² + kx + 49 = (x + 7)² olmalıdır; açılımdaki orta terim 2·7·x = 14x\'tir. Bu yüzden k = 14.'),
  ('9x² − 30x + m ifadesi bir iki terimlinin karesi olduğuna göre m kaçtır?', '25', ['5', '10', '100'], '9x² = (3x)² ve −30x = −2·3x·5 olduğundan ifade (3x − 5)²\'dir; sabit terim 5² = 25 olur.'),
  ('Pozitif a ve b için 4x² + 12x + 9 = (ax + b)² özdeşliği sağlanıyorsa a + b toplamı kaçtır?', '5', ['6', '13', '21'], '4x² + 12x + 9 = (2x + 3)² olduğundan a = 2, b = 3 ve a + b = 5\'tir.'),
  ('(x − 2)³ ifadesinin açılımı aşağıdakilerden hangisidir?', 'x³ − 6x² + 12x − 8', ['x³ − 6x² − 12x − 8', 'x³ − 8', 'x³ − 2x² + 4x − 8'], '(a − b)³ = a³ − 3a²b + 3ab² − b³ özdeşliğinde a = x, b = 2 alınır: x³ − 6x² + 12x − 8.'),
  ('x³ + 27 ifadesinin çarpanlarına ayrılmış biçimi hangisidir?', '(x + 3)(x² − 3x + 9)', ['(x + 3)(x² + 3x + 9)', '(x + 3)³', '(x − 3)(x² + 3x + 9)'], 'İki küp toplamı a³ + b³ = (a + b)(a² − ab + b²) özdeşliğiyle ayrılır; b = 3 için (x + 3)(x² − 3x + 9) bulunur.'),
  ('a³ − b³ = 56 ve a − b = 2 olduğuna göre a² + ab + b² toplamı kaçtır?', '28', ['27', '54', '112'], 'a³ − b³ = (a − b)(a² + ab + b²) olduğundan 56 = 2·(a² + ab + b²) ve aranan değer 28\'dir.'),
  ('999² sayısı (1000 − 1)² biçiminde yazılarak hesaplanırsa sonuç kaçtır?', '998 001', ['999 001', '9 998 001', '997 001'], '(1000 − 1)² = 1 000 000 − 2 000 + 1 = 998 001 bulunur.'),
  ('İki gerçek sayının toplamı 7 ve çarpımı 10\'dur. Bu sayıların karelerinin toplamı kaçtır?', '29', ['49', '39', '129'], 'a² + b² = (a + b)² − 2ab = 49 − 20 = 29\'dur.'),
  ('(a + b)² = a² + 2ab + b² özdeşliği, kenarı a + b olan bir karenin parçalanmasıyla gösterilir. Bu karede hangi parçalar bulunur?', 'İki kare ve iki eş dikdörtgen', ['Dört eş kare', 'Bir kare ve dört eş dik üçgen', 'İki dikdörtgen ve bir kare'], 'Kenarı a + b olan kare; alanı a² ve b² olan iki kareyle alanları ab olan iki eş dikdörtgene ayrılır. Toplam a² + 2ab + b² olur.'),
  ('x² − x − 20 üç terimlisinin çarpanlarına ayrılmış biçimi hangisidir?', '(x − 5)(x + 4)', ['(x + 5)(x − 4)', '(x − 10)(x + 2)', '(x − 20)(x + 1)'], 'Çarpımı −20, toplamı −1 olan iki sayı −5 ve 4\'tür. Bu yüzden x² − x − 20 = (x − 5)(x + 4).'),
  ('x² + 11x + 24 ifadesini birinci dereceden iki çarpanın çarpımı olarak yazınız. Hangisi doğrudur?', '(x + 3)(x + 8)', ['(x + 4)(x + 6)', '(x + 2)(x + 12)', '(x − 3)(x − 8)'], 'Çarpımları 24, toplamları 11 olan sayılar 3 ve 8\'dir. 4 ile 6\'nın toplamı 10, 2 ile 12\'nin toplamı 14 olduğundan uymaz.'),
  ('x² + 7x + 10 ve x² + 3x − 10 ifadelerinin ortak çarpanı hangisidir?', 'x + 5', ['x + 2', 'x − 2', 'x − 5'], 'x² + 7x + 10 = (x + 2)(x + 5) ve x² + 3x − 10 = (x + 5)(x − 2) olduğundan ortak çarpan x + 5\'tir.'),
  ('x² − (a + b)x + ab ifadesi her a ve b için hangi çarpıma eşittir?', '(x − a)(x − b)', ['(x + a)(x + b)', '(x − a)(x + b)', '(x − ab)(x − 1)'], '(x − a)(x − b) açılırsa x² − bx − ax + ab = x² − (a + b)x + ab elde edilir.'),
  ('x − 1/x = 2 ise x² + 1/x² ifadesinin değeri kaçtır?', '6', ['2', '4', '10'], '(x − 1/x)² = x² − 2 + 1/x² olduğundan 4 = x² + 1/x² − 2 ve aranan değer 6 olur.'),
  ('a + b + c = 6 ve ab + bc + ca = 11 olduğuna göre a² + b² + c² kaçtır?', '14', ['25', '36', '58'], '(a + b + c)² = a² + b² + c² + 2(ab + bc + ca) özdeşliğinden 36 = a² + b² + c² + 22 ve sonuç 14\'tür.'),
  ('(a + b − c)² ifadesinin açılımında bc teriminin katsayısı kaçtır?', '−2', ['2', '−1', '1'], 'Açılımda her ikili çarpım iki kez gelir: 2·b·(−c) = −2bc. Bu yüzden katsayı −2\'dir.'),
  ('x ≠ −3 olmak üzere (x² − 9)/(x² + 6x + 9) kesrinin en sade biçimi hangisidir?', '(x − 3)/(x + 3)', ['(x + 3)/(x − 3)', 'x − 3', '−1 + 6x/(x + 3)²'], 'Pay (x − 3)(x + 3), payda (x + 3)²\'dir. Ortak çarpan x + 3 sadeleşince (x − 3)/(x + 3) kalır.'),
  ('Pay ve paydası çarpanlarına ayrıldığında (x² − 5x + 6)/(x² − 4) rasyonel ifadesi neye sadeleşir?', '(x − 3)/(x + 2)', ['(x − 2)/(x + 2)', '(x + 3)/(x − 2)', '(x − 3)/(x − 2)'], 'Pay (x − 2)(x − 3), payda (x − 2)(x + 2)\'dir. x − 2 sadeleşince (x − 3)/(x + 2) bulunur.'),
  ('1/(x − 1) − 1/(x + 1) farkı tek bir kesir olarak yazıldığında hangisi elde edilir?', '2/(x² − 1)', ['−2/(x² − 1)', '2x/(x² − 1)', '0'], 'Ortak payda (x − 1)(x + 1) = x² − 1\'dir. Paylar (x + 1) − (x − 1) = 2 olur.'),
  ('x ≠ 1 için (2x² + x − 3)/(x − 1) ifadesi hangi polinoma eşittir?', '2x + 3', ['2x − 3', 'x + 3', '2x² + 3'], '2x² + x − 3 = (x − 1)(2x + 3) olduğundan bölüm 2x + 3\'tür.'),
  ('x = 2026 için (x² − 1)/(x − 1) − x ifadesinin değeri kaçtır?', '1', ['0', '2026', '2027'], '(x² − 1)/(x − 1) = x + 1 olduğundan ifade x + 1 − x = 1\'dir; x\'in değerinden bağımsızdır.'),
  ('Bir öğrenci (x + 3)/(x + 5) kesrinde x\'leri sadeleştirip 3/5 yazıyor. Bu işlemdeki hata nedir?', 'Toplamdaki terim sadeleştirilemez', ['Payda sıfır olabilir', 'Pay ile payda yer değiştirmelidir', 'Önce x yerine 1 yazılıp sonuç denetlenmelidir'], 'Sadeleştirme yalnız pay ve paydadaki ortak çarpanlarla yapılabilir. x burada çarpan değil, bir toplamın terimidir; örneğin x = 1 için kesir 4/6 = 2/3\'tür, 3/5 değildir.'),
  ('x ≠ y olmak üzere (x − y)/(y − x) kesrinin değeri kaçtır?', '−1', ['1', '0', 'x − y'], 'Payda y − x = −(x − y) olduğundan kesir (x − y)/(−(x − y)) = −1\'dir.'),
  ('P(x) = (2x − 1)⁴·(x + 3)³ polinomunun baş katsayısı kaçtır?', '16', ['8', '2', '48'], 'Baş katsayı, çarpanların baş katsayılarının uygun kuvvetlerinin çarpımıdır: 2⁴·1³ = 16.'),
  ('2026² − 2025·2027 işleminin sonucu kaçtır?', '1', ['0', '−1', '4051'], '2025·2027 = (2026 − 1)(2026 + 1) = 2026² − 1 olduğundan fark 1\'dir.'),
  ('Kökleri 1, −1 ve 2 olan, baş katsayısı 1 olan üçüncü dereceden polinom hangisidir?', 'x³ − 2x² − x + 2', ['x³ + 2x² − x − 2', 'x³ − 2x² + x − 2', 'x³ − x² − 2x + 2'], 'P(x) = (x − 1)(x + 1)(x − 2) = (x² − 1)(x − 2) = x³ − 2x² − x + 2 olur.'),
  ('Çarpımları 6 olan a ve b sayıları için a²b + ab² = 30 ise bu iki sayının toplamı nedir?', '5', ['6', '24', '180'], 'a²b + ab² = ab(a + b) olduğundan 30 = 6(a + b) ve a + b = 5\'tir.'),
  ('Sıfırdan farklı x için x + 1/x ile x − 1/x ifadelerinin kareleri arasındaki fark, yani (x + 1/x)² − (x − 1/x)², kaçtır?', '4', ['2', '0', '2x²'], 'İki kare farkıyla [(x + 1/x) − (x − 1/x)]·[(x + 1/x) + (x − 1/x)] = (2/x)(2x) = 4 bulunur.'),
  ('İki değişkenli x²y − y³ farkından önce y dışarı alınıp sonra kalan kısım ayrılırsa ne bulunur?', 'y(x − y)(x + y)', ['y(x − y)²', 'y²(x − y)', 'y(x² + y²)(x − y)(x + y)'], 'Önce ortak çarpan y alınır: y(x² − y²). Ardından iki kare farkı uygulanır.'),
  ('Kenarı x metre olan kare bir bahçenin bir kenarı 3 m uzatılıp diğer kenarı 3 m kısaltılarak dikdörtgen yapılıyor. Alan nasıl değişir?', '9 m² azalır', ['Değişmez', '9 m² artar', '6x m² azalır'], 'Yeni alan (x + 3)(x − 3) = x² − 9\'dur. Eski alan x² olduğundan alan her durumda 9 m² azalır.'),
  ('Kenarı 11 cm olan bir küp ile kenarı 10 cm olan bir küpün hacimleri farkı, a³ − b³ = (a − b)(a² + ab + b²) özdeşliğiyle hesaplanıyor. Fark kaç cm³\'tür?', '331', ['121', '300', '1331'], '(11 − 10)(121 + 110 + 100) = 1·331 = 331 cm³ bulunur.'),
  ('(x − 2)(x + 2)(x² + 4) + 16 ifadesi en sade hâliyle neye eşittir?', 'x⁴', ['x⁴ + 32', 'x⁴ − 16', '(x² + 4)²'], '(x − 2)(x + 2) = x² − 4 ve (x² − 4)(x² + 4) = x⁴ − 16\'dır. 16 eklenince x⁴ kalır.'),
  ('P(x) = 4 + 3x − x³ polinomu terimleri azalan derecelere göre sıralanarak yazıldığında ilk terim ne olur?', '−x³', ['4', '3x', 'x³'], 'Azalan derece sıralamasında en yüksek dereceli terim başa yazılır: −x³ + 3x + 4. İlk terim işaretiyle birlikte −x³\'tür.'),
  ('3x⁴ − 2x + x⁴ + 5 ifadesinde benzer terimler birleştirildiğinde kaç terimli bir polinom elde edilir?', '3', ['4', '2', '5'], '3x⁴ ile x⁴ benzer terimlerdir ve 4x⁴ olarak birleşir. Sonuç 4x⁴ − 2x + 5 olup üç terimlidir.'),
  ('İki polinomun her x için eşit (özdeş) olmasının koşulu aşağıdakilerden hangisidir?', 'Karşılıklı katsayıları eşit olmalıdır', ['Yalnız baş katsayıları eşit olmalıdır', 'Sabit terimleri eşit olmalıdır', 'Katsayı toplamları eşit olmalıdır'], 'İki polinom ancak her dereceden terimin katsayısı karşılıklı eşitse özdeştir. Baş katsayı, sabit terim ya da katsayı toplamının eşitliği tek başına yetmez.'),
  ('(x² + 3x − 1) + (2x² − 5x + 4) toplamı aşağıdakilerden hangisidir?', '3x² − 2x + 3', ['3x² + 2x + 3', '3x² − 2x − 5', '3x⁴ − 2x² + 3'], 'Benzer terimler toplanır: x² + 2x² = 3x², 3x − 5x = −2x, −1 + 4 = 3.'),
  ('(4x³ − x + 2) − (x³ + 2x² − x) farkı hangi polinomdur?', '3x³ − 2x² + 2', ['3x³ + 2x² + 2', '3x³ − 2x² − 2x + 2', '5x³ − 2x² + 2'], 'Çıkarılan polinomun her teriminin işareti değişir: 4x³ − x³ = 3x³, 0 − 2x² = −2x², −x + x = 0, sabit 2 kalır.'),
  ('Köklerinden biri 0 olan bir polinomun hangi katsayısı kesinlikle sıfırdır?', 'Sabit terim', ['Baş katsayı', 'x\'li terimin katsayısı', 'x²\'li terimin katsayısı'], 'P(0) sabit terime eşittir. 0 kök ise P(0) = 0, yani sabit terim sıfırdır.'),
  ('x⁴ − 10x² + 9 polinomunun dört kökünün çarpımı kaçtır?', '9', ['−9', '10', '−10'], 'Dördüncü dereceden polinomda kökler çarpımı sabit terim/baş katsayıdır (çift derece olduğundan işaret değişmez): 9. Gerçekten kökler ±1 ve ±3\'tür.'),
  ('Paydaları ortak olan x²/(x − 1) ve 1/(x − 1) kesirlerinin farkı, x ≠ 1 için sadeleştirilince ne kalır?', 'x + 1', ['x − 1', 'x² − 1', '1'], 'Paydalar aynı olduğundan (x² − 1)/(x − 1) = (x − 1)(x + 1)/(x − 1) = x + 1 bulunur.'),
  ('(x + 1)/(x² − 5x + 6) rasyonel ifadesini tanımsız yapan x değerleri hangileridir?', '2 ve 3', ['−1', '−2 ve −3', '1 ve 6'], 'Payda (x − 2)(x − 3) olduğundan x = 2 ve x = 3\'te sıfır olur; bu değerlerde ifade tanımsızdır.'),
  ('Matematikteki \'polinom\' teriminin Türkçe karşılığı aşağıdakilerden hangisidir?', 'Çok terimli', ['Çok bilinmeyenli', 'Üslü ifade', 'Çok değişkenli'], 'Polinom, \'çok\' anlamındaki poli- önekiyle \'terim\' anlamı taşıyan bir kökten oluşur; Türkçede \'çok terimli\' olarak karşılanır.'),
  ('x² − 5x + 6 gibi üç terimden oluşan polinomlara verilen ad hangisidir?', 'Trinom (üç terimli)', ['Binom (iki terimli)', 'Monom (tek terimli)', 'Kübik (üçüncü dereceli)'], 'Terim sayısına göre tek terimliye monom, iki terimliye binom, üç terimliye trinom denir.'),
  ('Eş merkezli iki çemberin yarıçapları R ve r\'dir. R + r = 10 cm ve R − r = 2 cm ise aradaki halkanın alanı kaç cm²\'dir?', '20π', ['12π', '40π', '100π'], 'Halka alanı π(R² − r²) = π(R − r)(R + r) = π·2·10 = 20π cm²\'dir.'),
  ('Bir öğrenci x² − 5x + 6 = (x − 2)(x + 3) yazmıştır. Bu eşitlikteki hata nedir?', 'İkinci çarpan x − 3 olmalıdır', ['Birinci çarpan x + 2 olmalıdır', 'Çarpanlar (x − 1)(x − 6) olmalıdır', 'Eşitlik doğrudur'], '(x − 2)(x + 3) = x² + x − 6 olur. Çarpımı 6, toplamı −5 olan sayılar −2 ve −3\'tür; doğrusu (x − 2)(x − 3).'),
  ('Bir öğrenci (x³ − 8)/(x − 2) bölümünü x² + 4 olarak buluyor. Doğru sonuç hangisidir?', 'x² + 2x + 4', ['x² − 2x + 4', 'x² + 4x + 4', 'x² + 2x + 4 + 16/(x − 2)'], 'x³ − 8 = (x − 2)(x² + 2x + 4) olduğundan bölüm x² + 2x + 4\'tür. Öğrencinin unuttuğu orta terim 2x\'tir.'),
  ('P(x) = x²⁰²⁶ − x + 1 polinomunun x = −1 için değeri kaçtır?', '3', ['1', '−1', '2026'], '2026 çift olduğundan (−1)²⁰²⁶ = 1\'dir. P(−1) = 1 + 1 + 1 = 3 bulunur.'),
  ('İki değişkenli 2x² + 3xy + y² ifadesi birinci dereceden iki çarpana nasıl ayrılır?', '(2x + y)(x + y)', ['(2x + y)(x + 2y)', '(x + y)²', '(2x − y)(x − y)'], '(2x + y)(x + y) = 2x² + 2xy + xy + y² = 2x² + 3xy + y² olur.'),
  ('x ≠ 0 için x² + 1/x² − 2 ifadesi hangi ifadenin karesidir?', 'x − 1/x', ['x + 1/x', 'x − 1', '1 − x²'], '(x − 1/x)² = x² − 2·x·(1/x) + 1/x² = x² − 2 + 1/x² olduğundan ifade (x − 1/x)²\'dir.'),
  ('Dört terimin de katsayısı 1 olan x³ + x² + x + 1 toplamı ikişerli gruplanırsa hangi çarpım ortaya çıkar?', '(x + 1)(x² + 1)', ['(x + 1)³', '(x − 1)(x² + 1)', '(x + 1)(x − 1)(x² + 1)'], 'x²(x + 1) + (x + 1) = (x + 1)(x² + 1) olur; x² + 1 gerçek sayılarda daha fazla ayrılamaz.'),
  ('Küp toplamı x³ + 1 ile kare farkı x² − 1 ifadelerini birlikte bölen en yüksek dereceli polinom hangisidir?', 'x + 1', ['x − 1', 'x² − x + 1', '1'], 'x³ + 1 = (x + 1)(x² − x + 1) ve x² − 1 = (x − 1)(x + 1)\'dir; ortak çarpan x + 1\'dir.'),
  ('x ≠ 1 olmak üzere x + 1/(x − 1) toplamı tek bir kesir olarak yazılırsa hangisi bulunur?', '(x² − x + 1)/(x − 1)', ['(x² + 1)/(x − 1)', '(x + 1)/(x − 1)', '(x² − x + 1)/(x² − 1)'], 'x = x(x − 1)/(x − 1) yazılır; pay x² − x + 1 olur.'),
  ('P(x) = (x − 1)(x − 2)(x − 3) + 4 polinomu için P(1) + P(2) + P(3) toplamı kaçtır?', '12', ['4', '6', '−12'], 'x = 1, 2, 3 değerlerinde çarpım sıfır olduğundan her biri 4 verir; toplam 12\'dir.'),
  ('x⁴ = 16 denklemini sağlayan gerçek sayılar hangileridir?', '−2 ve 2', ['Yalnız 2', '−2, 2 ve ±2i', '−4 ve 4'], 'x⁴ − 16 = (x² − 4)(x² + 4) = 0\'dır. x² + 4 gerçek sayılarda sıfır olmaz; gerçek çözümler x = ±2\'dir.'),
  ('x³ + 8 = 0 denkleminin gerçek sayılardaki çözümü kaçtır?', '−2', ['2', '−2 ve 2', '−8'], 'x³ + 8 = (x + 2)(x² − 2x + 4) ve ikinci çarpanın diskriminantı 4 − 16 < 0\'dır. Tek gerçek çözüm x = −2\'dir.'),
  ('Derecesi n ≥ 1 olan gerçek katsayılı bir polinomun en çok kaç farklı gerçek kökü olabilir?', 'n', ['n − 1', 'n + 1', '2n'], 'Her gerçek kök r için x − r bir çarpandır; n. dereceden bir polinoma en çok n birinci dereceden çarpan sığar.'),
  ('Küp toplamı ve küp farkı açılımlarını hatırlayan biri (x + 1)(x² − x + 1) − (x − 1)(x² + x + 1) farkını hangi sabite eşit bulur?', '2', ['0', '2x³', '−2'], 'İlk çarpım x³ + 1, ikinci çarpım x³ − 1\'dir. Farkları 2 olup x\'e bağlı değildir.'),
  ('x ≠ 0 ve x ≠ −1 için (1 + 1/x)(1 − 1/(x + 1)) çarpımının değeri kaçtır?', '1', ['x', '1/x', '(x + 1)/x'], '1 + 1/x = (x + 1)/x ve 1 − 1/(x + 1) = x/(x + 1)\'dir. Çarpımları 1 olur.'),
  ('x/(x² + 1) rasyonel ifadesi gerçek sayılarda hangi x değerleri için tanımsızdır?', 'Her gerçek x için tanımlıdır', ['Yalnız x = 0 için', 'x = 1 ve x = −1 için', 'Yalnız x = −1 için'], 'Payda x² + 1 her gerçek x için en az 1\'dir ve sıfır olmaz. Bu yüzden ifade bütün gerçek sayılarda tanımlıdır.'),
  ('(x⁴ − 1)/(x² + 1) kesri sadeleştirildiğinde hangi polinom elde edilir?', 'x² − 1', ['x² + 1', 'x³ − 1', '(x − 1)(x² + 1)'], 'x⁴ − 1 = (x² − 1)(x² + 1) olduğundan x² + 1 sadeleşir; x² + 1 hiçbir gerçek sayıda sıfır olmadığından ek koşul gerekmez.'),
  ('Alanı a² + 6a + 9 cm² olan bir karenin bir kenarı kaç cm\'dir (a > 0)?', 'a + 3', ['a + 9', 'a² + 3', '3a'], 'a² + 6a + 9 = (a + 3)² olduğundan karenin kenarı a + 3 cm\'dir.'),
  ('Hacmi x³ + 3x² + 3x + 1 cm³ olan bir küpün bir ayrıtı kaç cm\'dir (x > 0)?', 'x + 1', ['x + 3', 'x² + 1', '3x + 1'], 'x³ + 3x² + 3x + 1 = (x + 1)³ olduğundan küpün ayrıtı x + 1 cm\'dir.'),
  ('Uzunluğu 2x + 1 metre, genişliği x − 2 metre olan dikdörtgen biçimli bir halının alanını veren polinom hangisidir?', '2x² − 3x − 2', ['2x² + 3x − 2', '2x² − 5x − 2', '3x − 1'], '(2x + 1)(x − 2) = 2x² − 4x + x − 2 = 2x² − 3x − 2 olur.'),
  ('Bir atölyenin x ürün satışından elde ettiği gelir R(x) = 50x − x², toplam maliyeti C(x) = 10x + 300 polinomlarıyla veriliyor. Kârı veren K(x) = R(x) − C(x) polinomu hangisidir?', '−x² + 40x − 300', ['−x² + 60x + 300', '−x² + 40x + 300', 'x² − 40x + 300'], 'Fark alınırken maliyetin her teriminin işareti değişir: 50x − x² − 10x − 300 = −x² + 40x − 300.'),
  ('Toplamları 5 olan a ve b için a² + 2ab + b² − a − b ifadesi toplam cinsinden yazılırsa sonuç ne çıkar?', '20', ['25', '30', '−20'], 'İfade (a + b)² − (a + b) = 25 − 5 = 20 olarak yazılır.'),
  ('x³ − 2x² − 3x ifadesi tamamen çarpanlarına ayrıldığında hangi sonuç elde edilir?', 'x(x − 3)(x + 1)', ['x(x + 3)(x − 1)', '(x − 3)(x² + 1)', 'x(x − 3)(x + 1)²'], 'Önce x ortak çarpanı alınır: x(x² − 2x − 3). Ardından x² − 2x − 3 = (x − 3)(x + 1) olarak ayrılır.'),
  ('Katsayıları 3\'ün katı olan 3x³ − 12x² + 12x üç terimlisi en sade çarpım biçiminde nasıl yazılır?', '3x(x − 2)²', ['3x(x + 2)²', '3(x − 2)³', '3x(x − 2)(x + 2)'], '3x ortak çarpanı alınca x² − 4x + 4 kalır; bu da (x − 2)² tam karesidir.'),
  ('x ≠ 0 ve x ≠ 1 için (x² + x − 2)/(x² − x) kesrinin en sade hâli hangisidir?', '(x + 2)/x', ['(x − 2)/x', '(x + 2)/(x − 1)', 'x + 2'], 'Pay (x + 2)(x − 1), payda x(x − 1)\'dir. x − 1 sadeleşince (x + 2)/x kalır.'),
  ('Aşağıdaki eşitliklerden hangisi bir özdeşliktir?', '(x − 1)(x + 1) = x² − 1', ['x² = 4', '2x + 1 = 7', 'x² + 1 = 0'], 'Özdeşlik, değişkenin her değeri için doğru olan eşitliktir. Diğer seçenekler yalnız belirli değerlerde (ya da hiçbir gerçek değerde) sağlanan denklemlerdir.'),
  ('Bir öğrenci (x + 1)(x + 2) çarpımını x² + 2 olarak yazıyor. Öğrencinin unuttuğu terim hangisidir?', '3x', ['2x', 'x', '2x + x²'], 'Doğru açılım x² + 2x + x + 2 = x² + 3x + 2\'dir. Öğrenci dış ve iç çarpımlardan gelen x ve 2x terimlerini atlamıştır.'),
  ('Bir öğrenci a²b² − 1 ifadesini (ab − 1)² olarak çarpanlarına ayırıyor. Doğru ayrışım hangisidir?', '(ab − 1)(ab + 1)', ['(a − 1)(b + 1)', '(a²b − 1)(b − 1)', '(a²b − 1)(b + 1)'], 'a²b² − 1 = (ab)² − 1² bir iki kare farkıdır. (ab − 1)² ise a²b² − 2ab + 1\'e eşittir.'),
  ('x² + 5x + 7 üç terimlisi (x + 1)(x + 4) çarpımından bir k sabiti kadar fazladır. k sabiti kaçtır?', '3', ['7', '4', '−3'], '(x + 1)(x + 4) = x² + 5x + 4 olduğundan k = 7 − 4 = 3\'tür.'),
  ('P(P(x)) bileşke polinomu dokuzuncu dereceden ise P(x)\'in derecesi kaçtır?', '3', ['9', '4,5', '81'], 'P n. dereceden ise P(P(x)) n² dereceden olur. n² = 9\'dan n = 3 bulunur.'),
  ('Uzun hesap yapmadan (1001³ − 1)/(1001² + 1001 + 1) bölümünü küp farkı özdeşliğiyle bulunuz.', '1000', ['1001', '999', '1 000 000'], 'a³ − 1 = (a − 1)(a² + a + 1) özdeşliğinde a = 1001 alınırsa bölüm a − 1 = 1000 olur.'),
  ('Hipotenüsü 50 cm, bir dik kenarı 14 cm olan bir dik üçgenin diğer dik kenarı, √(50² − 14²) ifadesi iki kare farkıyla hesaplanırsa kaç cm bulunur?', '48', ['36', '44', '√2696'], '50² − 14² = (50 − 14)(50 + 14) = 36·64 olduğundan karekök 6·8 = 48\'dir.'),
  ('Ondalık sayılarla verilen 5,7² − 4,3² farkını kareleri tek tek almadan hesaplayan biri hangi sonucu bulur?', '14', ['1,96', '10', '1,4'], '(5,7 − 4,3)(5,7 + 4,3) = 1,4·10 = 14 bulunur.'),
  ('Hacmi x³ + 5x² + 6x cm³ olan bir dikdörtgenler prizmasının taban alanı x² + 2x cm²\'dir. Prizmanın yüksekliği kaç cm\'dir?', 'x + 3', ['x + 2', 'x + 6', 'x² + 3'], 'x³ + 5x² + 6x = x(x + 2)(x + 3) ve taban alanı x(x + 2)\'dir. Yükseklik hacim/taban alanı = x + 3 olur.'),
  ('P(x) + Q(x) = 3x² − 1 ve P(x) − Q(x) = x² + 2x + 5 olduğuna göre P(x) polinomu hangisidir?', '2x² + x + 2', ['x² − x − 3', '4x² + 2x + 4', '2x² + 2x + 2'], 'Eşitlikler toplanırsa 2P(x) = 4x² + 2x + 4 olur; P(x) = 2x² + x + 2.'),
  ('n. dereceden tek değişkenli bir polinom en çok kaç terimden oluşabilir?', 'n + 1', ['n', '2n', 'n(n + 1)'], 'Terimlerin dereceleri n, n − 1, …, 1, 0 olabilir; bu da en çok n + 1 terim demektir.'),
  ('Polinomlarda çarpma işleminin etkisiz (birim) elemanı hangisidir?', 'P(x) = 1 sabit polinomu', ['P(x) = 0 sıfır polinomu', 'P(x) = x birinci derece polinomu', 'P(x) = −1'], 'Her polinom 1 ile çarpıldığında kendisi kalır. Sıfır polinomu ise toplama işleminin etkisiz elemanıdır.'),
  ('1000 TL yıllık r faiz oranıyla iki yıl bileşik faize yatırılıyor. Birikimi veren 1000(1 + r)² polinomu açıldığında r\'li terimin katsayısı kaçtır?', '2000', ['1000', '200', '20 000'], '1000(1 + 2r + r²) = 1000 + 2000r + 1000r² olur; r\'nin katsayısı 2000\'dir.'),
  ('Bir öğrenci 6x² + 3x ifadesinde ortak çarpan alıp 3x(2x) yazıyor. Doğru sonuç hangisidir?', '3x(2x + 1)', ['3x(2x + 3)', '3(2x² + x)', 'x(6x + 1)'], '3x ÷ 3x = 1 olduğundan parantezin içinde 1 kalmalıdır. Öğrenci bu terimi unutmuştur; doğru sonuç 3x(2x + 1)\'dir.'),
  ('Bir öğrenci x² − 4x + 4 ifadesini (x − 4)² olarak yazıyor. Doğru tam kare hangisidir?', '(x − 2)²', ['(x + 2)²', '(x − 4)(x + 1)', '(x − 2)(x + 2)'], '(x − 4)² = x² − 8x + 16\'dır. x² − 4x + 4 ifadesinde sabit terim 2²\'dir ve orta terim −2·2·x olduğundan doğrusu (x − 2)²\'dir.'),
  ('Bir öğrenci 1/(a + b) = 1/a + 1/b yazıyor. a = b = 1 alınarak yapılan denetim ne gösterir?', '1/2 ≠ 2 çıkar; eşitlik yanlıştır', ['İki taraf da 1/2 çıkar; eşitlik doğrudur', 'İki taraf da 2 çıkar; eşitlik doğrudur', 'Denetim yapılamaz, çünkü a = b\'dir'], 'a = b = 1 için 1/(1 + 1) = 1/2, 1/1 + 1/1 = 2 olur. Tek bir karşı örnek, eşitliğin özdeşlik olmadığını gösterir.'),
  ('Bir polinom x² + 1\'e bölündüğünde bölüm x − 1, kalan 2x bulunuyor. Bölünen polinom hangisidir?', 'x³ − x² + 3x − 1', ['x³ − x² + x − 1', 'x³ + x² + 3x − 1', 'x³ − x² + x + 1'], 'Bölünen = bölen·bölüm + kalan = (x² + 1)(x − 1) + 2x = x³ − x² + x − 1 + 2x = x³ − x² + 3x − 1.'),
  ('Katsayıları 1, −2, 3, −6 olan üçüncü derece polinom, ilk iki ve son iki terimi gruplanarak x − 2\'ye bölünürse bölüm ne olur?', 'x² + 3', ['x² − 3', 'x² + 3x', 'x² − 2x + 3'], 'Gruplama ile x²(x − 2) + 3(x − 2) = (x − 2)(x² + 3) bulunur; bölme kalansızdır.'),
  ('x ≠ 0 için (x − 1/x)/(x + 1/x) ifadesi pay ve payda x ile çarpılarak sadeleştirilirse hangisi bulunur?', '(x² − 1)/(x² + 1)', ['(x − 1)/(x + 1)', '(x² + 1)/(x² − 1)', '(x² − 1)/(x² + 1)²'], 'Pay x ile çarpılınca x² − 1, payda x ile çarpılınca x² + 1 olur.'),
  ('Bir öğrenci x³ − 27 ifadesini (x − 3)(x² − 3x + 9) biçiminde ayırıyor. İkinci çarpanın doğru biçimi hangisidir?', 'x² + 3x + 9', ['x² − 6x + 9', 'x² − 3x − 9', 'x² + 6x + 9'], 'Küp farkında a³ − b³ = (a − b)(a² + ab + b²) olduğundan orta terim + işaretlidir. (x − 3)(x² − 3x + 9) ise x³ − 6x² + 18x − 27 verir.'),
  ('Bir sayının karesi ile o sayının 10 eksiği ve 10 fazlasının çarpımı arasındaki fark, yani n² − (n − 10)(n + 10), kaçtır?', '100', ['20', '10', 'n² − 100'], '(n − 10)(n + 10) = n² − 100 olduğundan fark her n için 100\'dür.'),
  ('Katsayılarından biri irrasyonel olan x² − 2√2x + 2 üç terimlisi neyin karesine eşittir?', 'x − √2', ['x − 2', 'x + √2', 'x − 2√2'], '(x − √2)² = x² − 2√2x + 2 olur; katsayılar irrasyonel olsa da tam kare özdeşliği aynen geçerlidir.'),
  ('x³ − 3x² + 3x − 9 ifadesi gruplandırılarak hangi çarpıma ayrılır?', '(x − 3)(x² + 3)', ['(x − 3)(x² − 3)', '(x + 3)(x² − 3)', '(x + 3)(x² + 3)'], 'x²(x − 3) + 3(x − 3) = (x − 3)(x² + 3) bulunur.'),
  ('Bir polinomda en yüksek dereceli terime (katsayısıyla birlikte) ne ad verilir?', 'Baş terim', ['Sabit terim', 'Orta terim', 'Benzer terim'], 'Örneğin 5x³ − 2x + 1 polinomunda baş terim 5x³, baş katsayı 5\'tir.'),
  ('Dört terimli a³ + 3a²b + 3ab² + b³ ifadesinin bir küp açılımı olduğunu fark eden biri, a = 3 ve b = −2 için hangi sonucu bulur?', '1', ['5', '−1', '35'], 'İfade (a + b)³ açılımıdır. a + b = 1 olduğundan değer 1³ = 1\'dir.'),
  ('Orta katsayısı 4054 olan x² − 4054x + 2027² üç terimlisi x = 2027 noktasında hangi değeri alır?', '0', ['2027', '4054', '2027²'], '4054 = 2·2027 olduğundan ifade (x − 2027)² tam karesidir ve x = 2027\'de 0 olur.'),
  ('Bir öğrenci x ≠ 1 için (x² − 1)/(x − 1) = x − 1 yazıyor. Doğru sonuç hangisidir?', 'x + 1', ['x', 'x² + 1', '1'], 'x² − 1 = (x − 1)(x + 1) olduğundan x − 1 sadeleşince x + 1 kalır. Örneğin x = 3 için (9 − 1)/2 = 4 = 3 + 1\'dir.'),
  ('Bir öğrenci x⁴ − 16 ifadesini (x² − 4)² biçiminde yazıyor. Bu ifadenin doğru ilk adım ayrışımı hangisidir?', '(x² − 4)(x² + 4)', ['(x² − 4)(x² − 4)', '(x − 4)(x + 4)', '(x² − 8)(x² + 2)'], 'x⁴ − 16 = (x²)² − 4² bir iki kare farkıdır. (x² − 4)² ise x⁴ − 8x² + 16 eder.'),
  ('Bir öğrenci x² + y² = (x + y)(x − y) yazıyor. Bu eşitlik hakkında hangisi doğrudur?', 'Yanlıştır; sağ taraf x² − y²\'ye eşittir', ['Doğrudur, iki kare toplamı özdeşliğidir', 'Yalnız x > y iken doğrudur', 'Yalnız x ve y pozitifken doğrudur'], '(x + y)(x − y) = x² − y²\'dir. x² + y² ise gerçek katsayılı birinci dereceden çarpanlara ayrılamaz (y ≠ 0 için).'),
  ('On tane x² − k² çarpanından oluşan (x² − 1)(x² − 4)(x² − 9)⋯(x² − 100) çarpımı açılırsa en yüksek üs kaç olur?', '20', ['10', '100', '200'], 'Çarpanlar k = 1, 2, …, 10 için x² − k² biçimindedir; on tane ikinci dereceden çarpan derece 20 verir.'),
  ('r sayısının P(x) polinomunun kökü olması ne anlama gelir?', 'P(r) = 0 olması', ['P(0) = r olması', 'r\'nin baş katsayı olması', 'P(r) = 1 olması'], 'Bir polinomun kökü (sıfırı), polinomun değerini sıfır yapan sayıdır.'),
  ('Bir ürünün birim fiyatı, satılan adet x olmak üzere 100 − x lira olarak belirleniyor. Toplam geliri veren polinom hangisidir?', '100x − x²', ['100 − x²', '100x + x²', 'x² − 100x'], 'Gelir = adet × birim fiyat = x(100 − x) = 100x − x²\'dir.'),
  ('Kenarı x metre olan kare bir arsanın bir kenarı 2 m kısaltılıp diğer kenarı 5 m uzatılıyor. Yeni alanı veren polinom hangisidir?', 'x² + 3x − 10', ['x² − 3x − 10', 'x² + 7x − 10', 'x² + 3x + 10'], '(x − 2)(x + 5) = x² + 5x − 2x − 10 = x² + 3x − 10 olur.'),
  ('P(x) = 0·x³ + 2x + 1 olarak yazılmış polinomun derecesi kaçtır?', '1', ['3', '0', '2'], 'Derece, katsayısı sıfırdan farklı olan en yüksek kuvvettir. x³\'ün katsayısı 0 olduğundan polinom 2x + 1\'dir ve birinci derecedendir.'),
  ('(3x²y)·(−2xy³) tek terimlilerinin çarpımı hangisidir?', '−6x³y⁴', ['−6x²y³', 'x³y⁴', '−5x³y⁴'], 'Katsayılar çarpılır: 3·(−2) = −6. Aynı tabanlı kuvvetlerin üsleri toplanır: x²·x = x³, y·y³ = y⁴.'),
  ('Aşağıdakilerden hangisi 3x²y terimiyle benzer terimdir?', '−5x²y', ['3xy²', '3x²y²', 'x³y'], 'Benzer terimlerde değişkenler ve üsleri aynıdır; yalnız katsayı farklı olabilir. −5x²y\'de de x\'in üssü 2, y\'nin üssü 1\'dir.'),
  ('Paydaları birbirinin ters işaretlisi olan 1/(x − 1) ve 1/(1 − x) kesirleri toplanırsa (x ≠ 1) sonuç ne olur?', '0', ['2/(x − 1)', '1', '−2/(x − 1)'], '1/(1 − x) = −1/(x − 1) olduğundan iki kesir birbirini götürür.'),
  ('Boyu eninin 2 katı olan bir dikdörtgenin eni x cm\'dir. Çevresini ve alanını veren polinomlar sırasıyla hangileridir?', '6x ve 2x²', ['3x ve 2x²', '6x ve x²', '4x ve 2x²'], 'Kenarlar x ve 2x\'tir. Çevre 2(x + 2x) = 6x, alan x·2x = 2x² olur.'),
  ('Bir aracın t saniyede aldığı yol s(t) = t² + 3t metredir. Araç t = 2 ile t = 4 arasında kaç metre yol alır?', '18', ['28', '10', '8'], 's(4) = 16 + 12 = 28 ve s(2) = 4 + 6 = 10\'dur. Aradaki yol 28 − 10 = 18 metredir.'),
  ('Herhangi bir tam sayının karesi, kendisi ve 1 toplanarak elde edilen n² + n + 1 sayısının tek-çiftliği hakkında ne söylenebilir?', 'Tek sayıdır', ['Çift sayıdır', '3\'ün katıdır', 'Asal sayıdır'], 'n² + n = n(n + 1) ardışık iki sayının çarpımı olarak çifttir; 1 eklenince sonuç tek olur.'),
  ('Biri ikinci, diğeri birinci dereceden olan x² + 1 ve x + 1 için ortak bölen araştırılıyor. Sonuç hangisidir?', '1', ['x + 1', 'x² + 1', 'x − 1'], 'x + 1\'in kökü −1\'dir ve x² + 1 bu noktada 2 değerini alır; ortak birinci dereceden çarpan yoktur. Bu yüzden polinomlar aralarında asaldır.'),
  ('x⁴ + 3x² + 2 ifadesi x² cinsinden düşünülerek hangi çarpıma ayrılır?', '(x² + 1)(x² + 2)', ['(x² + 1)(x² + 3)', '(x + 1)(x + 2)', '(x² − 1)(x² − 2)'], 'x² = t ile t² + 3t + 2 = (t + 1)(t + 2) olur; iki çarpan da gerçek sayılarda daha fazla ayrılamaz.'),
  ('Bir polinom birinci dereceden bir polinoma bölündüğünde kalan için hangisi kesinlikle doğrudur?', 'Kalan bir sabittir', ['Kalan birinci derecedendir', 'Kalan her zaman sıfırdır', 'Kalan ikinci dereceden olabilir'], 'Kalanın derecesi bölenden küçük olmalıdır; bölen birinci dereceden olunca kalan sabit (ya da sıfır) olur.'),
  ('Çarpanlara ayırarak denklem çözerken kullanılan \'çarpım sıfır kuralı\' neyi söyler?', 'a·b = 0 ise a = 0 ya da b = 0\'dır', ['a·b = 0 ise a = b\'dir', 'a + b = 0 ise a·b = 0\'dır', 'a·b = 1 ise a = b = 1\'dir'], 'Gerçek sayılarda iki sayının çarpımı ancak çarpanlardan en az biri sıfırsa sıfır olur. Bu yüzden çarpanlarına ayrılmış denklemde her çarpan ayrı ayrı sıfıra eşitlenir.'),
  ('Bir ifadeyi çarpanlarına ayırırken genellikle ilk olarak hangi yöntemin denenmesi önerilir?', 'Ortak çarpan parantezine alma', ['Terim ekleyip çıkarma', 'Değişken değiştirme', 'Rasyonel kök denemesi'], 'Ortak çarpan önce dışarı alınırsa kalan ifade sadeleşir ve özdeşlikler daha kolay görülür; örneğin 2x³ − 8x önce 2x(x² − 4) yapılır.'),
  ('Ortak çarpanı olmayan dört terimli bir ifadeyi çarpanlarına ayırmak için çoğunlukla hangi yöntem denenir?', 'Gruplandırma', ['Küp toplamı', 'Tam kareye tamamlama', 'Horner bölmesi'], 'Dört terim ikişerli gruplanıp her gruptan ortak çarpan alınınca çoğu zaman iki grupta ortak bir parantez ortaya çıkar.'),
  ('x⁴ + 1 polinomu x² + 1\'e bölündüğünde bölüm ve kalan sırasıyla hangileridir?', 'x² − 1 ve 2', ['x² + 1 ve 0', 'x² − 1 ve 0', 'x² ve 1'], '(x² + 1)(x² − 1) = x⁴ − 1 olduğundan x⁴ + 1 = (x² + 1)(x² − 1) + 2\'dir.'),
  ('Gerçek katsayılı bir polinom fonksiyonu hangi gerçek sayılar için tanımlıdır?', 'Bütün gerçek sayılar için', ['Yalnız pozitif sayılar için', 'Kökleri dışındaki sayılar için', 'Yalnız tam sayılar için'], 'Polinomda yalnız toplama, çıkarma ve doğal sayı üslü çarpma bulunur; payda ya da kök içi koşulu yoktur. Bu yüzden her gerçek x için değer hesaplanabilir.'),
  ('x ile y\'nin yerleri değiştirildiğinde değişmeyen polinomlara simetrik polinom denir. Aşağıdakilerden hangisi simetrik değildir?', 'x²y − y', ['x² + y²', 'x²y + xy²', 'xy + x + y'], 'x ile y yer değiştirince x²y − y ifadesi y²x − x olur ve ilk ifadeye eşit değildir. Diğerlerinde değişim sonucu ifade aynı kalır.'),
  ('Her n pozitif tam sayısı için xⁿ − yⁿ ifadesini kesinlikle bölen iki terimli hangisidir?', 'x − y', ['x + y', 'x² + y²', 'x² − y²'], 'x = y yazıldığında xⁿ − yⁿ sıfır olur; bu yüzden x − y her n için çarpandır. x + y ise yalnız n çift olduğunda böler.'),
  ('x² − x polinomunun x + 1 ve x noktalarındaki değerleri arasındaki fark, yani P(x + 1) − P(x), sadeleşince ne kalır?', '2x', ['2x − 2', '1', 'x² + x'], 'P(x + 1) = (x + 1)² − (x + 1) = x² + x\'tir. P(x) çıkarılınca x² + x − x² + x = 2x kalır.'),
  ('(x + 1)(x + 2)(x + 3) = x³ + 6x² + 11x + 6 özdeşliğinde x = 10 alınırsa 11·12·13 çarpımı kaç bulunur?', '1716', ['1806', '1616', '1706'], 'x = 10 için 1000 + 600 + 110 + 6 = 1716 elde edilir.'),
  ('Gerçek katsayılı polinomlar kümesi aşağıdaki işlemlerden hangisine göre kapalı değildir?', 'Bölme', ['Toplama', 'Çıkarma', 'Çarpma'], 'İki polinomun toplamı, farkı ve çarpımı yine polinomdur. Bölümleri ise örneğin 1/x gibi polinom olmayan bir ifade olabilir.'),
  ('P(x) ve Q(x) polinomlar (Q sıfır polinomu değil) olmak üzere P(x)/Q(x) biçimindeki ifadelere ne ad verilir?', 'Rasyonel ifade', ['Kök ifade', 'Üslü ifade', 'Mutlak değerli ifade'], 'İki polinomun bölümü biçiminde yazılan ifadeler rasyonel ifadelerdir; tanım kümesinden paydayı sıfır yapan değerler çıkarılır.'),
  ('(x + y)² − 4xy ifadesi hangisine eşittir?', '(x − y)²', ['x² + y²', '(x + y)(x − y)', 'x² − 2xy'], '(x + y)² − 4xy = x² + 2xy + y² − 4xy = x² − 2xy + y² = (x − y)² olur.'),
  ('Bir öğrenci (x − 2)(x + 3) = 0 denkleminin köklerini 2 ve 3 olarak buluyor. Hata nedir?', 'İkinci kök −3 olmalıdır', ['Birinci kök −2 olmalıdır', 'Kökler 6 ve −6 olmalıdır', 'Denklemin kökü yoktur'], 'Çarpım sıfır kuralına göre x − 2 = 0 ya da x + 3 = 0\'dır; kökler 2 ve −3\'tür. Öğrenci x + 3 çarpanının işaretini yanlış okumuştur.'),
  ('Kesirli katsayılı x²/4 − y²/9 farkı iki kare farkı olarak ele alınırsa nasıl ayrılır?', '(x/2 − y/3)(x/2 + y/3)', ['(x/4 − y/9)(x/4 + y/9)', '(x/2 − y/3)²', '(x − y)(x + y)/36'], 'x²/4 = (x/2)² ve y²/9 = (y/3)² olduğundan iki kare farkı (x/2 − y/3)(x/2 + y/3) verir.'),
  ('Her gerçek x için √(x⁴ + 1 + 2x²) kökünün, kök içi bir tam kare olarak görülerek bulunan sade biçimi hangisidir?', 'x² + 1', ['x + 1', '|x| + 1', 'x² − 1'], 'Kök içi (x² + 1)²\'dir. x² + 1 her zaman pozitif olduğundan mutlak değere gerek kalmadan karekök x² + 1\'dir.'),
  ('Dört terimli x²y² + x² + y² + 1 ifadesinde x² ortak parantezi ilk iki terimden alınırsa sonuç ne olur?', '(x² + 1)(y² + 1)', ['(xy + 1)²', '(x² + y²)(xy + 1)', '(x + 1)²(y + 1)²'], 'x²(y² + 1) + (y² + 1) = (x² + 1)(y² + 1) olur.'),
  ('İkilik tabanda yazılmış 1011₂ sayısı, P(x) = x³ + x + 1 polinomunun hangi değerine karşılık gelir?', 'P(2) = 11', ['P(2) = 9', 'P(1) = 3', 'P(2) = 13'], 'Basamaklar katsayı gibi okunur: 1·2³ + 0·2² + 1·2 + 1 = P(2) = 8 + 2 + 1 = 11.'),
  ('Her sayının diğer ikisinin toplamıyla çarpılıp sonuçların toplandığı a(b + c) + b(c + a) + c(a + b) ifadesi neye eşittir?', '2(ab + bc + ca)', ['ab + bc + ca', '(a + b + c)²', '2abc'], 'Açılınca ab + ac + bc + ab + ca + cb elde edilir; her ikili çarpım iki kez geçer.'),
];
